    /**
     * Tests getting all LabResults.
     *
     * @return    Collection
     */
    public List<LabResult> testGetAll() throws Throwable {
    LOGGER.info( "LabResultTest:testGetAll() - Retrieving Collection of LabResults:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all LabResult : " );
    List<LabResult> collection  = null;

    try {
        // call the static get method on the LabResultService
        collection = service.getAllLabResult();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            LabResult currEntity  = null;
            Iterator<LabResult> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getLabResultId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

